import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "परिवार में कई लोगों को, ब्रेस्ट या ओवेरियन कैंसर? क्या कैंसर का खतरा, खानदान में चल सकता है? इसकी एक जेनेटिक जांच है, बी आर सी ए टेस्ट. आखिर तक देखिए.",
 "बी आर सी ए वन और टू, ऐसे जीन हैं, जो डी एन ए की टूट फूट ठीक करते हैं, और कैंसर से बचाते हैं. अगर इनमें कोई हानिकारक बदलाव हो, तो यह सुरक्षा कमज़ोर हो जाती है. यह बदलाव मां या पिता, किसी से भी आ सकता है, और हर बच्चे में, इसके जाने की पचास प्रतिशत संभावना होती है.",
 "खतरा कितना? आम महिलाओं में, जीवन भर में ब्रेस्ट कैंसर का खतरा, लगभग तेरह प्रतिशत है. हानिकारक बी आर सी ए बदलाव में, यह साठ प्रतिशत से ज़्यादा हो सकता है. ओवेरियन कैंसर का खतरा भी कई गुना बढ़ता है. पुरुषों में, ब्रेस्ट, प्रोस्टेट, और पैंक्रियास कैंसर का खतरा बढ़ता है.",
 "किसे यह जांच करवाने के बारे में सोचना चाहिए? पचास साल या कम उम्र में ब्रेस्ट कैंसर. किसी भी उम्र में ओवेरियन कैंसर. पुरुषों में ब्रेस्ट कैंसर. पैंक्रियास, या फैला हुआ प्रोस्टेट कैंसर. या परिवार में, पहले से पता बी आर सी ए बदलाव.",
 "जांच खून, या लार के सैंपल से होती है. जांच से पहले, और रिपोर्ट के बाद, जेनेटिक काउंसलिंग ज़रूरी है. आमतौर पर, अठारह साल से कम उम्र के बच्चों की यह जांच नहीं की जाती.",
 "रिपोर्ट के तीन नतीजे हो सकते हैं. पॉज़िटिव यानी खतरा ज़्यादा, पर कैंसर होना पक्का नहीं. नेगेटिव यानी हानिकारक बदलाव नहीं मिला, पर कैंसर का सामान्य खतरा बना रहता है. और वी यू एस, यानी अनिश्चित बदलाव. इसके आधार पर कोई बड़ा फैसला नहीं.",
 "पॉज़िटिव हो, तो डॉक्टर जल्दी और ज़्यादा बार जांच की सलाह दे सकते हैं. कुछ लोगों के लिए, बचाव की सर्जरी जैसे विकल्पों पर, विशेषज्ञ से चर्चा होती है. और जिन्हें कैंसर है, उनमें यह रिपोर्ट, इलाज चुनने में भी मदद कर सकती है.",
 "परिवार के लिए भी यह जानकारी कीमती है. भाई, बहन, और बच्चे, उसी बदलाव की जांच करवा सकते हैं. पुरुष भी. डरें नहीं, जानकारी ही बचाव है. और हर फैसला, डॉक्टर की सलाह से ही लें.",
 close_voice("क्या आपके परिवार में, किसी को ब्रेस्ट या ओवेरियन कैंसर हुआ है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/brcar_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/brca_{i}.wav"],check=True); f=f"/tmp/brca_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/brca_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
